from PIL import Image
import numpy as np, math
from scipy.optimize import least_squares
im=np.array(Image.open('observations/obs_0102.png').convert('RGB')).astype(int)
R,G,B=im[:,:,0],im[:,:,1],im[:,:,2]
fl=(abs(R-G)<25)&(R>120)&(R<190)&(G>110)&(B>90)&(B<165)&(R-B>15)
tops={}
for u in range(0,512):
    c=np.nonzero(fl[:,u])[0]
    if len(c): tops[u]=c.min()
# corner = argmin v
cu=min(tops,key=lambda u:tops[u]); print('corner u',cu,'v',tops[cu])
L=[(u,tops[u]) for u in range(4,cu-14,6)]; Rr=[(u,tops[u]) for u in range(cu+30,508,6)]
def unpack(p): 
    hr=math.radians(p[2]); return np.array(p[:2]),np.array([math.sin(hr),math.cos(hr)]),np.array([math.cos(hr),-math.sin(hr)])
def gp(cam,f,r,u,v):
    D=1.55*256/(v-256); return cam+D*f+(D*(u-256)/256)*r
def make(wl,wr):
    def res(p):
        cam,f,r=unpack(p); o=[]
        for u,v in L:
            g=gp(cam,f,r,u,v); o.append((g[0]-wl[1] if wl[0]=='x' else g[1]-wl[1])*20)
        for u,v in Rr:
            g=gp(cam,f,r,u,v); o.append((g[0]-wr[1] if wr[0]=='x' else g[1]-wr[1])*20)
        d=np.array([-2.46,1.45])-cam; D=d@f; Lat=d@r
        o+=[256+256*Lat/D-337.0, 256+256*1.55/D-396.0]
        return o
    return res
for wl,wr,name in [(('y',-1.30),('x',-3.30),'left=South right=West'),(('x',-3.30),('y',-1.30),'left=West right=South')]:
    best=None
    for g in [(-0.04,3.05,224.7),(-0.5,3.6,205),(0.3,3.3,215)]:
        s=least_squares(make(wl,wr),g)
        rms=float(np.sqrt(np.mean(np.array(s.fun)**2)))
        if best is None or rms<best[1]: best=(s.x,rms)
    print(name,[round(v,3) for v in best[0]],'cost',round(best[1],3))
